return HeroFeedbackSurface(
  seekGestureKey: const ValueKey('void-hero-scrub-gesture'),
  flashController: heroFlashController,
  onPlayPause: () => player.playPause(),
  onPrevious: () => player.previous(),
  onNext: () => player.next(),
  onSeek: (d) => player.seek(d),
  positionMs: () => player.songInfo?.position ?? 0,
  durationMs: () => player.songInfo?.duration ?? 0,
  onSeekPreview: isLinux
      ? ({
          required target,
          required duration,
          required fraction,
        }) {
          if (duration.inMilliseconds <= 0) {
            seekCrumbText.value = null;
            return;
          }
          final targetMs = target.inMilliseconds;
          final durationMs = duration.inMilliseconds;
          final pct = (fraction * 100).round();
          // Match RetroLcdDisplay formatting style: m:ss.
          seekCrumbText.value =
              '${formatClock(targetMs)} / ${formatClock(durationMs)} · ${pct}%';
        }
      : null,
  onSeekPreviewEnd: isLinux ? () => seekCrumbText.value = null : null,
  onVerticalDragUpdate: acceptVertical ? onHeroVerticalDrag : null,
  onVerticalDragEnd: acceptVertical ? onHeroVerticalDragEnd : null,
  child: child,
);

